#include <print>

int main() {
    int a = 20;
    int b = 3;

    std::println("a = {}, b = {}", a, b);
    std::println("a + b = {}", a + b);
    std::println("a - b = {}", a - b);
    std::println("a * 2 + b = {}", a * 2 + b);
    return 0;
}

